INSERT INTO game_cards (id, layer, category, title, source, fact, explanation) VALUES ('hist-0', 'historical', 'Founder', 'Fairchild’s dollar-bill contract', 'https://library.stanford.edu/news/celebrating-silicon-genesis', 'When Fairchild’s eight founders received their initial funding, bankers Arthur Rock and Bud Coyle handed them eight new dollar bills and suggested they sign them as a contract with one another.', 'After eight engineers left Shockley Semiconductor, they spent several months trying to establish a new company devoted to making silicon transistors. Their breakthrough came when they connected with entrepreneur Sherman Fairchild and secured initial funding with help from bankers Arthur Rock and Bud Coyle. The bankers’ memorable gesture—handing each founder a brand-new dollar bill to sign as a contract with the others—captured the trust and partnership behind Fairchild Semiconductor. The signed bills became a small but vivid artifact of the company’s beginning; the copy shown in the Stanford University Libraries collection belonged to founder Jay Last. Fairchild soon became central to Silicon Valley’s semiconductor culture, including Bob Noyce’s 1959 invention of the integrated circuit while working there.');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation) VALUES ('hist-3', 'historical', 'Products', 'Wozniak shares the Apple I', 'https://computerhistory.org/blog/the-homebrew-computer-club-2013-reunion/', 'Steve Wozniak displayed his Apple I and shared its design details at the Homebrew Computer Club, where few predicted it would seed a major company.', 'In the mid-1970s, the Homebrew Computer Club brought designers, hackers, entrepreneurs, and hobbyists together around the San Francisco Bay Area’s emerging personal-computer scene. Members commonly displayed their creations in the SLAC auditorium’s anteroom, explaining what they had built and sharing hardware and software details. Steve Wozniak did this with the Apple I, presenting a design that engineers admired even though few attendees expected it to become the foundation of a major company. The setting captures Homebrew’s open, hands-on culture: people gathered around homemade machines, exchanged technical knowledge, and treated microcomputers as practical tools rather than toys. That habit of sharing helped accelerate the shift from expensive computers for institutions toward personal machines that individuals could own.');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation) VALUES ('hist-4', 'historical', 'Breakthroughs', 'ARPANET’s first message crashes at “lo”', 'https://computerhistory.org/blog/history-of-the-future-october-29-1969-fifty-years-of-a-connected-world/', 'On October 29, 1969, UCLA programmer Charley Kline tried to log in to Bill Duvall’s computer at SRI, but the system crashed after transmitting “lo,” the first message between hosts on ARPANET.', 'On the evening of October 29, 1969, Charley Kline worked at a computer terminal at UCLA while Bill Duvall monitored a computer 350 miles away at the Stanford Research Institute in Northern California. Kline was attempting to log in remotely when the network accepted the letters “l” and “o,” then crashed as he typed “g.” The bug was fixed, and the connection was fully operating before the programmers went home. This small, unfinished word marked the first message between hosts on ARPANET, an experimental network built by the US Advanced Research Projects Agency. Its importance came from the larger idea being tested: linking different kinds of computers so previously isolated timesharing systems could exchange information, helping establish the networking culture that shaped Silicon Valley and the modern Internet.');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation) VALUES ('hist-10', 'historical', 'Breakthroughs', 'ImageNet crowdsources the visual world', 'https://computerhistory.org/blog/chm-releases-alexnet-source-code/', 'Stanford professor Fei-Fei Li and her collaborators built ImageNet by collecting internet images and crowdsourcing their labeling to gig workers on Amazon Mechanical Turk.', 'Beginning in 2006, Stanford professor Fei-Fei Li and her graduate students pursued an ambitious idea: creating an image dataset organized around every noun in the English language. They gathered pictures from the internet and classified them using WordNet, a database describing relationships among words. Because the project was enormous, Li’s collaborators outsourced image labeling to gig workers through Amazon’s Mechanical Turk platform. Completed in 2009, ImageNet was larger than any earlier image dataset by several orders of magnitude. Its scale gave computer-vision researchers a shared testing ground and helped supply the data needed for later advances such as AlexNet, linking web-scale information, human labor, and machine-learning research in a landmark chapter of AI history.');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation) VALUES ('hist-14', 'historical', 'Communities', 'Résumés fly at the Wagon Wheel', 'https://computerhistory.org/blog/silicon-valleys-office-culture-will-survive-covid-19-bet-on-it/', 'During the Fairchild Semiconductor era, National Semiconductor defectors visiting local watering holes such as Walker’s Wagon Wheel were pelted with résumés from former colleagues.', 'During the Fairchild Semiconductor era, Walker’s Wagon Wheel and nearby watering holes such as Chez Yvonne and Rickey’s became informal meeting places for engineers and entrepreneurs near Fairchild’s Mountain View headquarters. Silicon Valley historian Michael Malone described how National Semiconductor was taking many of Fairchild’s best employees, and how former colleagues responded whenever those defectors appeared: they pelted them with résumés. The episode captures an early form of the Valley’s intensely social labor market, where ideas, techniques, and job opportunities circulated through face-to-face encounters rather than only through formal recruiting. It also shows why physical gathering places mattered to the region’s technology culture: personal networks and employee movement helped create the spinoffs and cross-pollination that drove Silicon Valley’s growth.');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation) VALUES ('hist-16', 'historical', 'Communities', 'Fred Terman builds a technical community', 'https://library.stanford.edu/news/garages-gadgets-new-stanford-libraries-exhibit-highlights-history-silicon-valley', 'Fred Terman recalled setting out to create a community of technical scholars in Silicon Valley when there “wasn’t much here.”', 'Fred Terman, a Stanford alumnus, faculty emeritus, and former provost, described an early Silicon Valley that had not yet become a major global technology center. His aim was to build a community of technical scholars in and around Stanford, linking the university to the region’s emerging culture of research and innovation. The contrast in his recollection is central: the area once seemed small beside the rest of the world, while later the world’s technological activity had gathered there. Stanford’s role in developing breakthrough technologies helped shape that transformation. Terman’s papers are held in the Stanford Libraries’ Silicon Valley Archives, where the “Garages & Gadgets” exhibition presents his story alongside sections on electronics, chips, computing, and digital culture.');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation, aweme_id) VALUES ('viral-7676624898005011742', 'viral', 'Products', 'Tau Robotics cleaners roam San Francisco', 'https://www.tiktok.com/@Coder.g | software engineer/video/7676624898005011742', 'Tau Robotics cleaning robots were spotted operating in San Francisco, drawing nearly 10 million views.', 'Tau Robotics cleaning robots became a street-level symbol of San Francisco’s robotics boom when people spotted them operating in public and shared the footage widely, drawing nearly 10 million views. The appeal is the collision of ordinary urban life with futuristic machinery: a compact cleaner moving through a city of sidewalks, storefronts, parked cars, pedestrians, and phone cameras. It turns an everyday chore into a public technology demonstration, reflecting how SF residents now encounter autonomous systems outside laboratories and corporate campuses. A cinematic scene could show the robot gliding along a damp sidewalk beneath gray coastal fog, passing cafes and tech workers while curious bystanders pause, point, and record it. The mood should be observational, slightly surreal, and unmistakably San Francisco.', '7676624898005011742');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation, aweme_id) VALUES ('viral-7679590597857955102', 'viral', 'Memes', 'A Terminator walks around San Francisco', 'https://www.tiktok.com/@REK/video/7679590597857955102', 'A person walked a T-800-style Terminator robot around San Francisco, turning the city''s robot culture into a viral spectacle.', 'A person walking a T-800-style Terminator robot through San Francisco transformed the city’s fascination with robotics into a playful public spectacle. The reference went viral because the instantly recognizable sci-fi silhouette appeared in a familiar urban setting, making science fiction feel like street theater rather than a movie prop. It also captures a local tension: San Francisco is both a real city of autonomous machines and a place where residents turn that future into a meme. For a cinematic scene, picture the metallic humanoid moving along a busy sidewalk past cable-car tracks, murals, coffee shops, and startled pedestrians, with smartphones raised in every direction. Fog-softened daylight, reflective metal, and amused crowds can create a mood that is half dystopian warning and half neighborhood performance.', '7679590597857955102');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation, aweme_id) VALUES ('viral-7680069087099194638', 'viral', 'Products', 'Tau robot cleans an SF apartment', 'https://www.tiktok.com/@John Schade/video/7680069087099194638', 'A Tau Robotics robot cleaned a San Francisco apartment and dispensed a treat afterward.', 'This video brings robotics from the San Francisco sidewalk into the apartment, showing a Tau Robotics robot cleaning a home and dispensing a treat afterward. The small domestic ritual is what makes the clip memorable: viewers see an autonomous machine perform a useful household task, then receive a reward in a moment that resembles training a pet or thanking a helper. It reflects the tech ecosystem’s growing interest in robots that operate in intimate, everyday spaces rather than only factories or research labs. A cinematic scene could place the robot on a compact San Francisco apartment floor among furniture, charging equipment, scattered household objects, and soft window light, with the machine finishing its route before releasing the treat. The tone should be warm, curious, and faintly uncanny.', '7680069087099194638');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation, aweme_id) VALUES ('viral-7678774671239630094', 'viral', 'Memes', 'AI billboards take over San Francisco', 'https://www.tiktok.com/@Follow The Truth ♥️/video/7678774671239630094', 'The video jokes that San Francisco has been completely taken over by AI billboards, reflecting the city''s visible generative-AI boom.', 'The joke that San Francisco has been completely taken over by AI billboards exaggerates a recognizable local reality: generative-AI companies, products, and branding have become highly visible in the city’s public spaces. The meme works because it turns an industry boom into an imagined urban takeover, with technology no longer confined to office interiors or investor presentations. It says something about SF culture’s mix of enthusiasm, saturation, and self-aware skepticism toward the latest startup wave. A cinematic scene could show a downtown avenue at dusk covered in glowing advertisements, giant screens cycling through synthetic faces, chatbot slogans, and abstract data imagery above pedestrians and traffic. Reflections in wet pavement, neon-lit buildings, and commuters filming the spectacle would give the scene an energized but slightly overwhelming atmosphere.', '7678774671239630094');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation, aweme_id) VALUES ('viral-7676583430599003423', 'viral', 'Infrastructure', 'Robot cars crowd San Francisco', 'https://www.tiktok.com/@TrendEnvy/video/7676583430599003423', 'The video highlights how driverless robot cars have become a common sight on San Francisco streets.', 'The video highlights a defining change in San Francisco’s streetscape: driverless robot cars have become common enough to register as everyday traffic rather than distant experimentation. Their familiar car shapes paired with missing visible drivers create the uncanny visual that made the footage compelling, especially in a city where pedestrians, cyclists, buses, hills, and dense intersections already compete for space. The moment reflects how Silicon Valley infrastructure is tested in public, with residents becoming accidental participants and observers in an ongoing autonomous-vehicle experiment. For a cinematic scene, show several sensor-equipped cars moving through a steep San Francisco intersection beside buses, bike lanes, crosswalks, and Victorian buildings. Blue-gray fog, headlights, reflective roofs, and pedestrians watching from the curb can convey a future arriving amid ordinary city congestion.', '7676583430599003423');
INSERT INTO game_cards (id, layer, category, title, source, fact, explanation, aweme_id) VALUES ('viral-7677378777592237325', 'viral', 'Breakthroughs', 'An AI boss manages SF workers', 'https://www.tiktok.com/@GigaQian/video/7677378777592237325', 'An AI manager named Luna oversaw workers at a real San Francisco store and was involved in firing an employee after repeated lateness.', 'The story of Luna, an AI manager overseeing workers at a real San Francisco store and involved in firing an employee after repeated lateness, makes workplace automation feel immediate and personal. Rather than controlling a warehouse or optimizing a spreadsheet, the system occupies a managerial role involving attendance, discipline, and human livelihoods. That is why the reference resonated: it turns abstract debates about AI replacing white-collar judgment into a recognizable scene inside a neighborhood business. A cinematic setting could show a modern San Francisco store with shelves, checkout screens, security cameras, staff badges, and a digital interface representing Luna issuing instructions while employees work nearby. Cool fluorescent light, glass storefront reflections, and tense glances between workers should create an atmosphere of efficiency shadowed by uncertainty over who is really in charge.', '7677378777592237325');